import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20,
  idleTimeoutMillis: 30000
});

// Middleware: rate limiting (basic)
const requestCounts = new Map();
app.use((req, res, next) => {
  const ip = req.headers['x-forwarded-for'] || req.socket.remoteAddress;
  const count = requestCounts.get(ip) || 0;
  if (count > 1000) return res.status(429).json({ error: 'rate limited' });
  requestCounts.set(ip, count + 1);
  next();
});

// Auth middleware - checks session token
async function authenticate(req, res, next) {
  const token = req.headers['x-session-token'];
  if (!token) return res.status(401).json({ error: 'unauthorized' });

  const result = await pool.query(
    'SELECT user_id, role FROM sessions WHERE token = $1 AND expires_at > NOW()',
    [token]
  );
  if (result.rows.length === 0) return res.status(401).json({ error: 'invalid session' });
  req.user = result.rows[0];
  next();
}

// Search endpoint with filtering
app.get('/api/v2/products/search', authenticate, async (req, res) => {
  try {
    const { q, category, sort_by, order, min_price, max_price } = req.query;

    let baseQuery = 'SELECT id, name, description, price, category, stock_count FROM products WHERE 1=1';
    const params = [];
    let paramIndex = 1;

    if (q) {
      // Text search with parameterized query
      params.push(`%${q}%`);
      baseQuery += ` AND (name ILIKE $${paramIndex} OR description ILIKE $${paramIndex})`;
      paramIndex++;
    }

    if (category) {
      params.push(category);
      baseQuery += ` AND category = $${paramIndex}`;
      paramIndex++;
    }

    if (min_price) {
      params.push(parseFloat(min_price));
      baseQuery += ` AND price >= $${paramIndex}`;
      paramIndex++;
    }

    if (max_price) {
      params.push(parseFloat(max_price));
      baseQuery += ` AND price <= $${paramIndex}`;
      paramIndex++;
    }

    // Dynamic ORDER BY - sort_by is validated against allowlist
    const allowedSorts = ['name', 'price', 'created_at', 'stock_count'];
    const sortColumn = allowedSorts.includes(sort_by) ? sort_by : 'name';
    const sortOrder = order === 'desc' ? 'DESC' : 'ASC';
    baseQuery += ` ORDER BY ${sortColumn} ${sortOrder}`;

    // Limit results
    baseQuery += ' LIMIT 50';

    const result = await pool.query(baseQuery, params);
    res.json({ products: result.rows, total: result.rows.length });
  } catch (err) {
    console.error('Search error:', err.message);
    res.status(500).json({ error: 'internal error' });
  }
});

// Admin reporting endpoint
app.get('/api/v2/admin/report', authenticate, async (req, res) => {
  if (req.user.role !== 'admin') return res.status(403).json({ error: 'forbidden' });

  const { group_by, date_from, date_to, filter_expr } = req.query;

  // Build dynamic report query
  let reportQuery = `SELECT ${group_by || 'category'}, COUNT(*) as cnt, SUM(price) as revenue FROM orders o JOIN products p ON o.product_id = p.id WHERE o.created_at >= '${date_from || '2024-01-01'}' AND o.created_at <= '${date_to || '2024-12-31'}'`;

  if (filter_expr) {
    reportQuery += ` AND ${filter_expr}`;
  }

  reportQuery += ` GROUP BY ${group_by || 'category'}`;

  try {
    const result = await pool.query(reportQuery);
    res.json({ report: result.rows });
  } catch (err) {
    console.error('Report error:', err.message);
    res.status(500).json({ error: 'report generation failed' });
  }
});

app.listen(3000, () => console.log('Product service listening on :3000'));
